  const tOf = impTimeFn_();
/** 改善檔的「版本時間」：自動匯入者用來源檔修改時間，手動上傳者用上傳時間 */
function impTimeFn_() {
  const srcT = {}; readTable_('改善來源').forEach(r => { if (r.系統檔案ID && r.修改時間) srcT[String(r.系統檔案ID)] = Date.parse(String(r.修改時間)) || 0; });
  return f => srcT[String(f.檔案ID)] || Date.parse(String(f.上傳時間 || '').replace(' ', 'T') + '+08:00') || 0;
}
/**
 * 改善檔依版本先後重新命名（系統維護）：同一案件最舊的為原名，較新的依序 _2、_3…
 *   args.dryRun 只回報；args.id 可只處理單一案件
 */
function apiImpRenumber(args, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const tOf = impTimeFn_();
    const C = {}; readTable_('案件').forEach(c => { C[c.案件編號] = c; });
    const by = {};
    readTable_('紀錄檔').filter(f => f.種類 === IMP_KIND && f.檔案ID && (!args.id || f.案件編號 === args.id)).forEach(f => { (by[f.案件編號] = by[f.案件編號] || []).push(f); });
    const src = readTable_('改善來源'), srcBy = {}; src.forEach(r => { if (r.系統檔案ID) srcBy[String(r.系統檔案ID)] = r; });
    const rep = [], t0 = Date.now();
    Object.keys(by).forEach(id => {
      const list = by[id], c = C[id];
      if (list.length < 2 || !c || Date.now() - t0 > 250000) return;
      list.sort((a, b) => tOf(a) - tOf(b));
      list.forEach((f, i) => {
        const ext = (String(f.檔名).match(/\.[A-Za-z0-9]{2,5}$/) || [''])[0];
        const base = recFileName_(c, 'x' + ext).replace(/_(督導|查核)紀錄_/, '_' + IMP_KIND + '_');
        const name = i ? base.replace(/(\.[A-Za-z0-9]{2,5})?$/, m => '_' + (i + 1) + m) : base;
        if (name === String(f.檔名)) return;
        rep.push({ 案件編號: id, 原檔名: String(f.檔名), 新檔名: name });
        if (args.dryRun) return;
        driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.檔案ID + '?supportsAllDrives=true', { method: 'patch', contentType: 'application/json', payload: JSON.stringify({ name: name }) });
        const old = f.檔名; f.檔名 = name; writeRow_('紀錄檔', f);
        const r = srcBy[String(f.檔案ID)]; if (r && String(r.說明 || '').indexOf(old) === 0) { r.說明 = name + String(r.說明).slice(String(old).length); writeRow_('改善來源', r); }
      });
    });
    if (!args.dryRun && rep.length) log_(user.Email, '改善檔依版本重新命名', args.id || '', { 筆數: rep.length });
    return rep;
  } finally { lock.releaseLock(); }
}
  impRenumber: [apiImpRenumber, ['系統維護']],
